293	  // mode) and the ELF scan is skipped: the binary need not contain a magic
294	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
295	  // run -- callers pass exactly one form.
296	  void enable_hybrid_handoff(const std::string& elf_path,
297	                             const std::string& state_out_path,
298	                             std::optional<uint64_t> exit_pc = std::nullopt,
299	                             bool drain_minimal = false)
300	  {
301	    hybrid::CsrTrigger trigger;
302	    if (exit_pc) {
303	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
304	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
305	    } else {
306	      auto elf = LIEF::ELF::Parser::parse(elf_path);
307	      if (!elf)
308	        throw std::runtime_error(
309	          "enable_hybrid_handoff: failed to parse " + elf_path);
310	      for (const auto& seg: elf->segments()) {
311	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
312	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
313	        const auto content = seg.content();
314	        const std::span<const uint8_t> bytes{content.data(), content.size()};
315	        trigger.scan_buffer(bytes, seg.virtual_address());
316	      }
317	    }
