320	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
321	                            PLATFORM::dmi_data_width>>(platform.dmi,
322	                                                       platform.clk.period());
323	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
324	                            v_scratch_gpa(), hybrid::andes_caps_from_config());
325	    if (hybrid_input_state_)
326	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
327	    hybrid_handoff_->set_minimal_drain(drain_minimal);
328	    hybrid_handoff_->set_block_store_drain(true);
329	    hybrid_drain_minimal_ = drain_minimal;
330	    hybrid_state_path_ = state_out_path;
