333	private:
334	  // L26: the GUEST address of the V-register transport page -- the top page of
335	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
336	  // so this sits just past the program's declared RAM and never collides with
337	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
338	  auto v_scratch_gpa() const -> uint64_t
339	  {
340	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
341	                                 platform.main_memory.data.size());
342	  }
343	
344	  // LG3: drain the freshly reset, just-halted hart into a baseline the
345	  // liveness gate compares restores against. The probe carries the incoming
346	  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
347	  // the gate will compare (it is flag-driven); every probe field it does not
348	  // re-read stays zero, matching what an absent block compares against.
349	  auto capture_reset_baseline(
350	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
351	                          PLATFORM::dmi_data_width>& bus,
352	    const hybrid_state_v1& input) -> hybrid_state_v1
353	  {
354	    hybrid::StateDrain drain(bus, v_scratch_gpa(),
355	                             hybrid::andes_caps_from_config());
356	    drain.set_gpr_block_store(true);
357	    drain.set_fpr_block_store(true);
358	    drain.set_csr_sweep(true);
359	    // At reset mstatus.FS/VS are Off, so the capture's fsd/vse8 sweeps (and
360	    // the FPR/V CSR abstract reads) would raise illegal instruction
361	    // (cmderr=3). Halt and enable them first, exactly like resume() does
362	    // before its FPR/V writes. Safe to clobber: mstatus is never re-read by
363	    // a drain nor gated by the baseline, and resume() rewrites it whenever
364	    // the FP/V flags are set -- the only case this branch runs.
365	    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
366	      using RD = hybrid::ResumeDriver;
367	      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
368	      bus.write(RD::kDmcontrol,
369	                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
370	      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
371	                             "reset-baseline capture halt");
372	      const uint64_t mstatus = hybrid::read_register_64(
373	        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
374	      uint64_t enable = mstatus;
375	      if ((input.flags & HYBRID_FLAG_FP)
376	          && (enable & RD::kMstatusFsMask) == 0)
377	        enable |= RD::kMstatusFsInitial;
378	      if ((input.flags & HYBRID_FLAG_V)
379	          && (enable & RD::kMstatusVsMask) == 0)
380	        enable |= RD::kMstatusVsInitial;
381	      if (enable != mstatus)
382	        hybrid::write_register_abstract(
383	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
384	    }
385	    hybrid_state_v1 probe{};
386	    probe.magic = HYBRID_STATE_MAGIC;
387	    probe.version = HYBRID_STATE_VERSION;
388	    probe.flags = input.flags;
389	    probe.vlenb = input.vlenb;
390	    auto baseline = drain.drain_with_passthrough(probe);
391	    lift_scratch_blocks(baseline, /*csr_swept=*/true);
392	    return baseline;
393	  }
394	
395	  // Lift the scratch-page transports into `state` (dual of the resume
396	  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
397	  // state carries vsim's actual V values, not QEMU 1's stale snapshot -- and
398	  // the drain sd/fsd block-store sweeps (x1..x30 / f0..f31) into the GPR/FPR
399	  // slots. Gated on the SAME fits conditions StateDrain used to pick
400	  // sweep-vs-abstract: when the V page is full it read the registers via
401	  // Abstract Commands and populated the state directly, so lifting stale
402	  // scratch would clobber correct values. x31 (the GPR sweep base) was
403	  // captured via abstract read inside the drain, so only x1..x30 lift.
404	  // Shared by the exit drain and the reset-baseline capture.
405	  //
406	  // csr_swept: whether the drain's Andes+M-ext csrr+sd sweep ran. False on a
407	  // minimal drain (drain_counters_only never sweeps, and nothing stages the
408	  // CSR region at resume -- the restore sweep is off -- so its bytes are
409	  // meaningless and lifting them would corrupt the passthrough values).
410	  void lift_scratch_blocks(hybrid_state_v1& state, bool csr_swept)
411	  {
412	    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
413	                                       platform.main_memory.data.size()};
414	    if ((state.flags & HYBRID_FLAG_V) != 0u)
415	      hybrid::read_v_from_scratch(state, ram);
416	    if (hybrid::gpr_scratch_fits(state.vlenb))
417	      hybrid::read_gpr_from_scratch(state, ram, 30);
418	    if ((state.flags & HYBRID_FLAG_FP) != 0u
419	        && hybrid::fpr_scratch_fits(state.vlenb))
420	      hybrid::read_fpr_from_scratch(state, ram);
421	    if (csr_swept
422	        && (state.flags & (HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT)) != 0u
423	        && hybrid::csr_scratch_fits(state.vlenb))
424	      hybrid::read_csr_from_scratch(state, ram,
425	                                    hybrid::andes_caps_from_config());
426	  }
