63	// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
64	// the self-describe half of the framework's hot-plug contract: andes-sim runs
65	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
66	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
67	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
68	static void describe_engine()
69	{
70	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
71	  const std::string prefix = "simulator_";
72	  if (cfg.starts_with(prefix))
73	    cfg = cfg.substr(prefix.size());
74	
75	  const std::string_view blob(&_binary_config_inc_start,
76	                              static_cast<size_t>(&_binary_config_inc_end
77	                                                  - &_binary_config_inc_start));
78	  auto scan_int = [blob](std::string_view key) -> long {
79	    size_t pos = blob.find(key);
80	    if (pos == std::string_view::npos)
81	      return 0;
82	    pos += key.size();
83	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
84	      ++pos;
85	    long v = 0;
86	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
87	      v = v * 10 + (blob[pos++] - '0');
88	    return v;
89	  };
90	  const long vlen = scan_int("NDS_VLEN");
91	  const long dlen = scan_int("NDS_DLEN");
92	  const long elen = scan_int("NDS_ELEN");
93	  const long xlen = scan_int("NDS_XLEN");
94	
95	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
96	  // placeholders out of fmt's brace parser.
97	  std::string json;
98	  json += "{\n";
99	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
100	  json += "  \"type\": \"verilator\",\n";
101	  json += "  \"kind\": \"cycle-accurate\",\n";
102	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
103	          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
104	          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
105	  json += "  \"triggers\": [\"csr\", \"pc\"],\n";
106	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
107	  json += "  \"state\": [\"resume\", \"drain\"],\n";
108	  // Andes custom CSRs this core actually implements (from its config.inc).
109	  // The driver uses this to skip --verify on CSRs the engine lacks, mirroring
110	  // the resume/drain gating in ResumeDriver/StateDrain (single binder).
111	  const std::vector<std::string> andes_csrs =
112	      hybrid::supported_andes_csr_names(hybrid::andes_caps_from_config());
113	  json += "  \"andes_csrs\": [";
114	  for (size_t i = 0; i < andes_csrs.size(); ++i)
115	    json += (i ? ", \"" : "\"") + andes_csrs[i] + "\"";
116	  json += "],\n";
117	  json += "  \"invoke\": {\n";
118	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
119	  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
120	          "\"--resume-from-qemu\", \"{state_in}\", "
121	          "\"--handoff-out\", \"{state_out}\", "
122	          "\"--shared-mem-path\", \"{mmap}\", "
123	          "\"--shared-mem-size\", \"{mmap_size}\", "
124	          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
125	  json += "  },\n";
126	  json += "  \"result\": \"stderr:cycles\"\n";
127	  json += "}\n";
128	  fwrite(json.data(), 1, json.size(), stdout);
