339	    p.longopt("shared-mem-base", u64_opt("shared-mem-base", args.shared_mem_base));
340	    p.longopt("resume-from-qemu", [&](const std::string_view s) {
341	      args.resume_from_qemu = s;
342	    });
343	    p.longopt("handoff-out", [&](const std::string_view s) {
344	      args.handoff_out = s;
345	    });
346	    p.longopt("hybrid-enter-pc", u64_opt("hybrid-enter-pc", args.hybrid_enter_pc));
347	    p.longopt("hybrid-exit-pc", u64_opt("hybrid-exit-pc", args.hybrid_exit_pc));
348	    p.longopt("reset-vector", [&](const std::string_view s) {
349	      args.reset_vectors.emplace_back(s);
350	    });
351	    p.posarg([&](const std::string_view s) { args.elf_file = s; });
352	    p.parse(std::vector<std::string_view>(argv, argv + argc));
353	    return args;
354	  }();
355	
356	#ifndef VSIMSAVABLE
357	  if (args.save_ctx || args.continue_ctx || args.context_dir != "./saved_ctx/")
358	  {
359	    spdlog::critical(
360	      "--save, --continue, and --context-dir require VSIMSAVABLE build");
361	    std::exit(EXIT_FAILURE);
362	  }
363	#endif
364	
365	  if (!args.resume_from_qemu.empty() && args.continue_ctx)
366	    throw std::runtime_error(
367	      "--resume-from-qemu and --continue are mutually exclusive");
368	
369	  print_version();
370	
371	  // systemc and cci init
372	  auto broker = cci_utils::broker{"global_broker"};
373	  cci::cci_register_broker(broker);
374	
375	  const auto time_resolution = sc_core::sc_get_time_resolution();
376	  spdlog::debug("Using time resolution: {}", time_resolution.to_string());
377	
378	  std::optional<MmapBacking> shared_ram;
379	  if (!args.shared_mem_path.empty()) {
380	    if (args.shared_mem_size == 0)
381	      throw std::runtime_error(
382	        "--shared-mem-path requires --shared-mem-size > 0");
383	    shared_ram.emplace(args.shared_mem_path, args.shared_mem_size);
384	  } else if (args.shared_mem_size != 0) {
385	    throw std::runtime_error(
386	      "--shared-mem-size requires --shared-mem-path");
387	  }
388	
389	  // Hybrid mode: the mmap window is the only RAM; QEMU virt has no alias.
390	  const MemoryRegion ram_region = shared_ram
391	    ? MemoryRegion{args.shared_mem_base,
392	                   args.shared_mem_base + args.shared_mem_size - 1}
393	    : MemoryRegion{RAM_BASE, RAM_END};
394	  const MemoryRegion ram_alias_region = shared_ram
395	    ? MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
396	                   SimpleMemory<32>::INVALID_ADDRESS}
397	    : MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END};
398	
399	  // run simulation
400	  const auto do_sim = [&]<typename CPU>() -> int {
401	    Simulator<CPU> sim{
402	      "sim",
403	      shared_ram ? shared_ram->span() : std::span<uint8_t>{},
404	      ram_region, ram_alias_region};
405	
406	    if (args.memmap) {
407	      sim.platform.interconnect.dump_region();
408	      return 0;
409	    }
410	
411	    sim.set_mem_latency(args.mem_latency);
412	
413	    if (!args.ilm_file.empty())
414	      sim.load_image(args.ilm_file, MEM_TYPE::ILM);
415	
416	    if (!args.dlm_file.empty())
417	      sim.load_image(args.dlm_file, MEM_TYPE::DLM);
418	
419	    // End of elaboration
420	    sc_core::sc_start(sc_core::SC_ZERO_TIME);
421	
422	    const auto t0 = std::chrono::steady_clock::now();
423	
424	    if (!args.waveform_file.empty())
425	      sim.enable_waveform(args.waveform_file);
426	
427	    if (!args.pc_trace_file.empty())
428	      sim.enable_pc_trace(args.pc_trace_file);
429	
430	    if (!args.kanata_file.empty() && !args.clarity_file.empty())
431	      throw std::runtime_error("--kanata and --clarity are mutually exclusive");
432	
433	    if (!args.kanata_file.empty())
434	      sim.enable_kanata(args.kanata_file, args.objdump_file);
435	
436	    if (!args.clarity_file.empty())
437	      sim.enable_clarity(args.clarity_file, args.objdump_file);
438	
439	    // In tier-2 hybrid resume, QEMU 1 already loaded the ELF into the
440	    // shared mmap. Re-loading would `std::fill_n(memsz - filesz, 0)` over
441	    // each PT_LOAD's .bss tail, wiping phase-1 writes to static buffers.
442	    // Still parse the ELF to set the reset vector -- between sim.reset()
443	    // and apply_resume_from_qemu's DMI halt, the hart fetches one or two
444	    // instructions from the reset vector; if that address is unmapped
445	    // the bus errors leave the hart in a state the resume cannot recover.
446	    const bool elf_already_in_shared_mmap =
447	      !args.resume_from_qemu.empty() && !args.shared_mem_path.empty();
448	    if (!args.elf_file.empty() && !args.continue_ctx)
449	      sim.load_elf(args.elf_file, /*skip_memory_load=*/elf_already_in_shared_mmap);
450	
451	    // Apply per-hart reset vector overrides (after load_elf sets defaults)
452	    for (const auto& s: args.reset_vectors) {
453	      auto [hart, addr] = parse_reset_vector(s);
454	      if (hart) {
455	        sim.set_reset_vector(*hart, addr);
456	      } else {
457	        for (size_t i = 0; i < sim.platform.reset_vector.size(); ++i)
458	          sim.set_reset_vector(i, addr);
459	      }
460	    }
461	
462	    if (args.continue_ctx)
463	      spdlog::info("You're resuming program from the given context");
464	
465	    if (args.jtag_port)
466	      sim.init_debug_port(args.jtag_port.value());
467	
468	    if (!args.jtag_port && args.elf_file.empty() && !args.continue_ctx
469	        && args.resume_from_qemu.empty())
470	      throw std::runtime_error(
471	        "Required arg : program, --jtag-port, or --resume-from-qemu");
472	
473	    if (args.continue_ctx || args.save_ctx) {
474	      std::string_view s = args.context_dir;
475	      if (std::filesystem::exists(s) && !std::filesystem::is_directory(s))
476	        throw std::runtime_error("Error: Path " + std::string{s}
477	                                 + " exists but is not a directory.");
478	      if (!std::filesystem::exists(s)) {
479	        try {
480	          std::filesystem::create_directories(s);
481	        } catch (const std::filesystem::filesystem_error& e) {
482	          throw std::runtime_error(std::string{"Failed to create directory: "}
483	                                   + e.what());
484	        }
485	      }
486	      sim.context_config = {args.save_ctx, args.continue_ctx, args.context_dir};
487	    }
488	
489	    sim.reset();
490	
491	    if (!args.resume_from_qemu.empty()) {
492	      // LG3: reset-baseline cache key = engine binary identity + ELF
493	      // identity (the hart free-runs a few workload instructions between
494	      // reset and the DMI halt, so the halted state is per-ELF; see
495	      // hybrid/reset_baseline.hpp). Empty path -> liveness gate off.
496	      std::string baseline_cache{};
497	      struct stat sim_bin{}, elf_bin{};
498	      if (const auto root = hybrid::reset_baseline_cache_root(
499	            std::getenv("XDG_CACHE_HOME"), std::getenv("HOME"));
500	          !args.no_reset_baseline && !root.empty() && !args.elf_file.empty()
501	          && ::stat("/proc/self/exe", &sim_bin) == 0
502	          && ::stat(args.elf_file.c_str(), &elf_bin) == 0) {
503	        baseline_cache =
504	          (root
505	           / hybrid::reset_baseline_file_name(
506	               std::filesystem::path(argv[0]).filename().string(),
507	               ANDESCYCLE_VERSION, uint64_t(sim_bin.st_mtime),
508	               uint64_t(sim_bin.st_size), uint64_t(elf_bin.st_mtime),
509	               uint64_t(elf_bin.st_size)))
510	            .string();
511	      }
512	      sim.apply_resume_from_qemu(args.resume_from_qemu, baseline_cache);
513	    }
514	
515	    if (args.hybrid_enter_pc)
516	      spdlog::warn("--hybrid-enter-pc=0x{:x} ignored: entry trigger is "
517	                   "QEMU's job (use plugin enter_pc= arg)",
518	                   *args.hybrid_enter_pc);
519	
520	    if (!args.handoff_out.empty())
521	      sim.enable_hybrid_handoff(args.elf_file, args.handoff_out,
522	                                args.hybrid_exit_pc, args.drain_minimal);
523	
524	    const int exit_code = sim.run();
525	
526	    sim.cpu.final();
527	
528	    const auto t1 = std::chrono::steady_clock::now();
529	    const auto cycles = sim.get_cycles();
530	    spdlog::info("{} cycles simulated", cycles);
531	    if (cycles > 0) {
532	      const auto ms =
533	        std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0);
534	      spdlog::info("{}.{:03}s elapsed, {:.3f}Hz", ms.count() / 1000,
535	                   ms.count() % 1000,
536	                   double(cycles) / double(ms.count()) * 1000.0);
537	    }
538	    return exit_code;
539	  };
540	
541	  return do_sim.operator()<VSIM_CPU_INTERFACE_CLASS>();
542	
543	} catch (const std::exception& e) {
544	  spdlog::critical("fatal exception: {}\n", e.what());
545	  std::exit(EXIT_FAILURE);
546	} catch (...) {
547	  std::terminate();
548	}
