56	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
57	                               int got_rc) {
58	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
59	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
60	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
61	  // to completion without ever hitting its ROI boundary -- the marker/pc
62	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
63	  // mistake; name the kind so the fix is obvious, not a bare exit code.
64	  if (got_rc == 0 && expect_rc == kDrainRc)
65	    m += " -- the " + s.role + " ran to completion without reaching its " +
66	         s.trigger.kind +
67	         " trigger boundary (the ROI never drained; check the ELF actually "
68	         "reaches the " +
69	         s.trigger.kind + ")";
70	  return m;
