126	std::vector<std::vector<std::string>> plan_argvs(
127	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
128	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
129	  std::vector<std::vector<std::string>> out;
130	  out.reserve(plan.steps.size());
131	  std::string prev_state_out;  // empty for the cold first leg
132	
133	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
134	  long vlen = 0;
135	  for (const Step& s : plan.steps)
136	    if (s.role == "accurate-leg")
137	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
138	        if (e->vlen > 0) vlen = e->vlen;
139	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
140	
141	  for (size_t i = 0; i < plan.steps.size(); ++i) {
142	    const Step& step = plan.steps[i];
143	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
144	    if (!eng) {
145	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
146	            step.engine_id + "'";
147	      return {};
148	    }
149	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
150	    if (!tmpl) {
151	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
152	            "' has no invoke template for role '" + step.role + "'";
153	      return {};
154	    }
155	
156	    std::string trig_err;
157	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
158	    if (!trig_err.empty()) {
159	      err = "plan step " + std::to_string(i) + ": " + trig_err;
160	      return {};
161	    }
162	
163	    const std::string state_out = state_path(workdir, i);
164	    const std::map<std::string, std::string> m = {
165	        {"bin", eng->bin_path},
166	        {"elf", plan.elf},
167	        {"plugin", ctx.plugin_path},
168	        {"mmap", ctx.mmap_path},
169	        {"mmap_size", std::to_string(ctx.mem_size)},
170	        {"mmap_base", ctx.mmap_base},
171	        {"state_in", prev_state_out},
172	        {"state_out", state_out},
173	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
174	        {"vlen", vlen_str},
175	    };
176	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
177	    if (!err.empty()) {
178	      err = "plan step " + std::to_string(i) + ": " + err;
179	      return {};
180	    }
181	    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
182	    // config.inc distilled to per-extension globals), so QEMU1 executes the same
183	    // extensions the engine models. Empty => keep the descriptor's default -cpu.
184	    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
185	      argv.push_back("-readconfig");
186	      argv.push_back(ctx.qemu_cfg);
187	    }
188	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
189	    // after the filled template (matches tests/e2e.sh's ordering).
190	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
191	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
192	    out.push_back(std::move(argv));
193	    prev_state_out = state_out;
194	  }
195	  err.clear();
196	  return out;
197	}
198	
199	PlanResult run_plan(const Plan& plan,
200	                    const std::vector<EngineDescriptor>& engines,
201	                    const PlanOptions& opts) {
202	  PlanResult res;
203	  if (plan.steps.empty()) {
204	    res.error = "plan has no steps";
205	    return res;
206	  }
207	
208	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
209	  std::string mmap_path = plan.mmap_path;
210	  const bool own_mmap = mmap_path.empty();
211	  if (own_mmap) {
212	    std::string err;
213	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
214	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
215	    if (mmap_path.empty()) {
216	      res.error = err;
217	      return res;
218	    }
219	  }
220	
221	  // A private dir for the threaded drain files.
222	  std::error_code ec;
223	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
224	  std::string tmpl = workdir.string();
225	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
226	  tbuf.push_back('\0');
227	  const char* made = ::mkdtemp(tbuf.data());
228	  if (!made) {
229	    if (own_mmap) ::unlink(mmap_path.c_str());
230	    res.error = "failed to create plan work dir";
231	    return res;
232	  }
233	  const std::string wd = made;
234	
235	  RuntimeCtx ctx;
236	  ctx.mmap_path = mmap_path;
237	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
238	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
239	  // linker script still uses only --mem-size, so the scratch page sits above
240	  // everything it can address.
241	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
242	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
243	
244	  // Match the QEMU producer leg's ISA to the accurate engine: ask that engine
245	  // for a QEMU -readconfig cfg distilled from its config.inc. Tolerant -- an
246	  // engine without --print-qemu-config leaves qemu_cfg empty (the parser throws
247	  // on the unknown flag -> non-zero exit), so the fast leg keeps its -cpu.
248	  for (const Step& s : plan.steps)
249	    if (s.role == "accurate-leg")
250	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id);
251	          e && !e->bin_path.empty()) {
252	        ctx.qemu_cfg = stage_qemu_cfg(
253	            wd, run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs));
254	        break;
255	      }
256	
257	  std::string err;
258	  const std::vector<std::vector<std::string>> argvs =
259	      plan_argvs(plan, engines, wd, ctx, err);
260	  if (!err.empty()) {
261	    res.error = err;
262	  } else if (opts.dry_run) {
263	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
264	    // threaded state paths) -- record them for the caller to print, spawn none.
265	    res.argvs = argvs;
266	  } else {
267	    res.argvs = argvs;
268	    for (size_t i = 0; i < argvs.size(); ++i) {
269	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
270	      if (r.spawn_failed) {
271	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
272	        break;
273	      }
274	      if (r.timed_out) {
275	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
276	                    std::to_string(opts.timeout_ms) + " ms";
277	        break;
278	      }
279	      if (r.rc != opts.expect_rc) {
280	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
281	        break;
282	      }
283	      const StateFile sf = read_state_file(state_path(wd, i));
284	      if (!sf.ok()) {
285	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
286	        break;
287	      }
288	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
289	    }
290	  }
291	
292	  fs::remove_all(wd, ec);
293	  if (own_mmap) ::unlink(mmap_path.c_str());
294	  return res;
295	}
296	
297	}  // namespace andes_sim
